import javax.imageio.ImageIO;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws curseforge/icon.png from scratch: a white border, a camouflage texture made from noise, drifting smoke,
 * and "SBW / FIX" in hand-made pixel letters. No font, no Superb Warfare asset, nothing generated by AI.
 * Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png [preview-64.png]
 */
public class MakeIcon {
    static final int GRID = 40;
    static final int CELL = 13;
    static final int BORDER = 2;
    static final long SEED = 2026_1013L;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x10140A;
    static final int SHADOW = 0x1C2412;
    /** Camouflage tones, darkest to lightest. */
    static final int[] CAMO = {0x26301A, 0x384627, 0x4D5D33, 0x667545, 0x7E8A57};
    /** Smoke, thinnest to thickest. */
    static final int[] SMOKE = {0x8E958A, 0xB3B8AE, 0xD3D6CF};

    static final String[] S = {
            ".######",
            "#######",
            "##.....",
            "##.....",
            "######.",
            ".######",
            ".....##",
            ".....##",
            ".....##",
            "#######",
            "######."};
    static final String[] B = {
            "######.",
            "#######",
            "##...##",
            "##...##",
            "######.",
            "######.",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "######."};
    static final String[] W = {
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##.#.##",
            "##.#.##",
            "#######",
            "#######",
            "###.###",
            "##...##"};
    static final String[] F = {
            "#######",
            "#######",
            "##.....",
            "##.....",
            "######.",
            "######.",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##....."};
    static final String[] I = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "######",
            "######"};
    static final String[] X = {
            "##...##",
            "##...##",
            ".##.##.",
            ".##.##.",
            "..###..",
            "..###..",
            "..###..",
            ".##.##.",
            ".##.##.",
            "##...##",
            "##...##"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = camo(x, y);
                int smoke = smoke(x, y);
                if (smoke >= 0) {
                    color[y][x] = SMOKE[smoke];
                }
            }
        }

        boolean[][] text = new boolean[GRID][GRID];
        int letterGap = 2;
        int lineGap = 4;
        int height = 11 + lineGap + 11;
        int y0 = (GRID - height) / 2;
        stamp(text, new String[][]{S, B, W}, letterGap, y0);
        stamp(text, new String[][]{F, I, X}, letterGap, y0 + 11 + lineGap);

        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && outline[y - 1][x - 1] && !outline[y][x]) {
                    color[y][x] = SHADOW;
                }
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) {
                    color[y][x] = WHITE;
                } else if (outline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) {
                    color[y][x] = WHITE;
                }
            }
        }

        BufferedImage image = new BufferedImage(GRID * CELL, GRID * CELL, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < GRID * CELL; y++) {
            for (int x = 0; x < GRID * CELL; x++) {
                image.setRGB(x, y, color[y / CELL][x / CELL]);
            }
        }
        ImageIO.write(image, "png", new File(args[0]));

        if (args.length > 1) {
            BufferedImage preview = new BufferedImage(64, 64, BufferedImage.TYPE_INT_RGB);
            preview.getGraphics().drawImage(image.getScaledInstance(64, 64, Image.SCALE_SMOOTH), 0, 0, null);
            ImageIO.write(preview, "png", new File(args[1]));
        }
    }

    /** Blotchy camouflage: two noise layers picked into four bands, with a dark edge. */
    static int camo(int x, int y) {
        double a = fbm(x / 7.0, y / 7.0, 0);
        double b = fbm(x / 4.0 + 17, y / 4.0 + 5, 1);
        double fromCenter = Math.max(Math.abs(x - (GRID - 1) / 2.0), Math.abs(y - (GRID - 1) / 2.0)) / ((GRID - 1) / 2.0);
        double level = a * 0.75 + b * 0.25 - Math.max(0.0, fromCenter - 0.7) * 0.8;
        int index = (int) Math.floor((level - 0.25) * 9.0);
        return CAMO[Math.max(0, Math.min(CAMO.length - 1, index))];
    }

    /** Smoke drifting in from the lower left and the upper right, thinning at its edges; -1 for none. */
    static int smoke(int x, int y) {
        double density = Math.max(
                puff(x, y, 6, 33, 15),
                puff(x, y, 35, 6, 11));
        density += (fbm(x / 3.0, y / 3.0, 2) - 0.5) * 0.7;
        if (density < 0.35) {
            return -1;
        }
        return density < 0.55 ? 0 : density < 0.8 ? 1 : 2;
    }

    static double puff(int x, int y, double cx, double cy, double radius) {
        return Math.max(0.0, 1.0 - Math.hypot(x - cx, y - cy) / radius);
    }

    static void stamp(boolean[][] mask, String[][] letters, int gap, int y0) {
        int width = 0;
        for (String[] letter : letters) {
            width += letter[0].length();
        }
        width += gap * (letters.length - 1);
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int col = 0; col < letter[row].length(); col++) {
                    if (letter[row].charAt(col) == '#') {
                        mask[y0 + row][x + col] = true;
                    }
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The mask plus every cell next to it, diagonals included. */
    static boolean[][] grow(boolean[][] mask) {
        boolean[][] out = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !out[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID && mask[ny][nx]) {
                            out[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return out;
    }

    static double fbm(double x, double y, int layer) {
        double sum = 0;
        double amplitude = 0.5;
        double total = 0;
        for (int octave = 0; octave < 4; octave++) {
            sum += amplitude * noise(x, y, layer * 16 + octave);
            total += amplitude;
            x *= 2.0;
            y *= 2.0;
            amplitude *= 0.5;
        }
        return sum / total;
    }

    /** Smoothly interpolated value noise in 0..1. */
    static double noise(double x, double y, int layer) {
        int x0 = (int) Math.floor(x);
        int y0 = (int) Math.floor(y);
        double fx = x - x0;
        double fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx);
        double sy = fy * fy * (3 - 2 * fy);
        double a = hash(x0, y0, layer);
        double b = hash(x0 + 1, y0, layer);
        double c = hash(x0, y0 + 1, layer);
        double d = hash(x0 + 1, y0 + 1, layer);
        return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;
    }

    static double hash(int x, int y, int layer) {
        long h = SEED ^ (x * 0x9E3779B97F4A7C15L) ^ (y * 0xC2B2AE3D27D4EB4FL) ^ (layer * 0x165667B19E3779F9L);
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) / (double) (1L << 53);
    }
}
